// 独立设计原型：页面化流程与正式页面互不影响。
const base = new URL('../../', location.href);
const app = document.querySelector('#app');
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths = { sea:'M3 6l5-2 8 2 5-2v15l-5 2-8-2-5 2V6 M8 4v15 M16 6v15', guide:'M4 4h6l2 2 2-2h6v15h-6l-2 2-2-2H4V4 M12 6v15', explore:'M11 3a8 8 0 1 0 0 16 8 8 0 0 0 0-16 M17 17l5 5', saved:'M6 3h12v18l-6-4-6 4V3', back:'M15 5l-7 7 7 7', expand:'M8 3H3v5 M16 3h5v5 M3 16v5h5 M21 16v5h-5', next:'M9 5l7 7-7 7' };
const icon = name => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name] || paths.next}"/></svg>`;
const tabs = [['sea','画海'],['guide','导览'],['explore','探索'],['saved','收藏']];
let works, periods, people, readings, credits, selected = 'mona-lisa', paused = false, pan = {x:0,y:0};
let favoriteIds = []; try { favoriteIds = JSON.parse(localStorage.getItem('aha.prototype.v2.favorites') || '[]'); if (!Array.isArray(favoriteIds)) favoriteIds = []; } catch {}
let model = {tab:'sea', stacks:Object.fromEntries(tabs.map(([id]) => [id,[{kind:'root',scroll:0,category:'works',query:''}]]))};
let timer;
const readingProgress = new Map();
const stack = () => model.stacks[model.tab];
const route = () => stack().at(-1);
const work = id => works.find(w => w.id === id);
const img = (id, full = false) => credits[id] ? new URL(full ? credits[id].optimized?.display || credits[id].file : credits[id].optimized?.thumb || credits[id].thumb, base).href : '';
const image = (w, full = false) => img(w.id, full) ? `<img src="${esc(img(w.id,full))}" alt="${esc(w.title)}" ${full?'':'loading="lazy"'} draggable="false">` : '<span>暂无配图</span>';
const period = id => periods.find(p => p.id === id);
const saveView = () => { const screen = app.querySelector('.screen'); if (screen) route().scroll = screen.scrollTop; };
function checkpoint(){ saveView(); history.replaceState({...history.state, prototype:structuredClone(model)},''); }
function push(next){ checkpoint(); const parent={tab:model.tab,depth:stack().length}; stack().push({...next,scroll:0}); history.pushState({prototype:structuredClone(model),parent},''); render(true); }
function replace(){ history.replaceState({...history.state,prototype:structuredClone(model)},''); render(); }
function back(){ if(route().kind==='reader')readingProgress.set(route().id,structuredClone(route())); const parent=history.state?.parent; if(parent?.tab===model.tab && parent.depth===stack().length-1){history.back();return;} if(stack().length>1)stack().pop(); replace(); }
function switchTab(id){ checkpoint(); const old=model.tab; model.tab=id; if(old===id)model.stacks[id]=[model.stacks[id][0]]; history.pushState({prototype:structuredClone(model)},''); render(true); }
function toast(message){ app.querySelector('.toast')?.remove(); const node=document.createElement('div');node.className='toast';node.setAttribute('role','status');node.textContent=message;app.append(node);clearTimeout(timer);timer=setTimeout(()=>node.remove(),1800); }
function toggleFavorite(id){ const has=favoriteIds.includes(id);favoriteIds=has?favoriteIds.filter(x=>x!==id):[id,...favoriteIds];let persisted=true;try{localStorage.setItem('aha.prototype.v2.favorites',JSON.stringify(favoriteIds));}catch{persisted=false;}saveView();render();toast(persisted?(has?'已取消收藏':'已加入收藏'): '仅在本次会话保留，浏览器未允许保存'); }
function openWork(id, ids=[id], scope='作品'){push({kind:'work',id,ids,scope});}
function tiles(list, scope){return `<div class="grid">${list.map(w=>`<button class="tile" data-work="${w.id}" data-scope="${scope}">${image(w)}<strong>${esc(w.title)}</strong><small>${esc(w.artist)}</small></button>`).join('')}</div>`;}
function rootSea(){const ids=['mona-lisa','birth-of-venus','school-of-athens','starry-night','impression-sunrise','last-supper','olympia','the-scream'].filter(id=>work(id));if(!ids.includes(selected))ids[0]=selected;const positions=[[54,49,106],[9,31,105],[86,22,105],[10,73,113],[83,79,112],[40,19,68],[92,53,78],[38,91,64]];const w=work(selected);return `<section class="sea-page"><div class="sea-heading"><h2>在画里，遇见世界。</h2><p>西方艺术 · 三万年的回声</p></div><div class="sea-tools"><button data-pause aria-label="${paused?'继续漂浮':'暂停漂浮'}" aria-pressed="${paused}">${paused?'▷':'Ⅱ'}</button><button data-sea-next aria-label="发现下一件作品">→</button></div><div class="sea-canvas" aria-label="拖动画海选择作品"><div class="sea-world ${paused?'paused':''}" style="transform:translate(${pan.x}px,${pan.y}px)">${Array.from({length:24},(_,i)=>`<span class="sky-dot" style="left:${(i*41)%100}%;top:${(i*67)%100}%">·</span>`).join('')}${ids.map((id,i)=>{const [x,y,width]=positions[i];return `<button class="art" data-select="${id}" aria-label="选择${esc(work(id).title)}" aria-pressed="${id===selected}" style="left:${x}%;top:${y}%;width:${width}px;opacity:${i>4?.63:1}">${image(work(id))}</button>`;}).join('')}</div></div><div class="sea-note"><div><strong>${esc(w.title)}</strong><p>${esc(w.artist)} · ${esc(w.yearText)}</p></div><button data-save="${w.id}" aria-label="${favoriteIds.includes(w.id)?'取消收藏':'收藏作品'}" aria-pressed="${favoriteIds.includes(w.id)}">${icon('saved')}</button><button class="go" data-work="${w.id}" data-scope="画海">看这件作品 ${icon('next')}</button></div></section>`;}
function rootGuide(){return `<div class="pad"><div class="eyebrow">跟着一个问题，走近作品</div><h2>今天，慢慢看。</h2><p class="lede">从三分钟开始，也可以走进一整个时代。</p>${readings.filter(r=>r.kind==='story').map(r=>`<button class="guide" data-story="${r.id}">${image(work(r.steps[0].works[0]),true)}<div style="padding-top:13px"><span class="pill">${r.minutes} 分钟 · ${r.steps.length} 步</span><h3>${esc(r.title)}</h3><p>${esc(r.deck)}</p></div></button>`).join('')}<div class="section-label"><h3>十八间展厅</h3><small>从史前走到现代</small></div>${periods.map((p,i)=>`<button class="list-row" data-hall="${p.id}"><b class="num">${String(i+1).padStart(2,'0')}</b><span><strong>${esc(p.short)}</strong><small>${esc(p.span)}</small></span>${icon('next')}</button>`).join('')}</div>`;}
function rootExplore(){const r=route();return `<div class="pad"><h2>找到你的好奇。</h2><p class="lede">作品、人物，和它们之间的联系。</p><button class="search-field" data-search style="text-align:left;color:#75806e">搜索作品或艺术家</button><div class="segments">${[['works','作品'],['people','人物'],['context','脉络']].map(([id,label])=>`<button data-category="${id}" aria-pressed="${r.category===id}">${label}</button>`).join('')}</div>${r.category==='people'?people.map(p=>`<button class="list-row" data-person="${p.id}"><span><strong>${esc(p.name)}</strong><small>${esc(p.en)}</small></span>${icon('next')}</button>`).join(''):r.category==='context'?`<div class="eyebrow">沿着时代看</div>${periods.map(p=>`<button class="list-row" data-hall="${p.id}"><span><strong>${esc(p.name)}</strong><small>${esc(p.span)}</small></span>${icon('next')}</button>`).join('')}`:`<button data-filter class="lede" style="margin-bottom:14px;padding:0">${esc(r.period?period(r.period)?.short:'全部时期')} ▾</button>${tiles(filteredWorks().slice(0,r.limit||24),'探索')}<button class="primary" data-more>继续浏览作品</button>`}</div>`;}
function filteredWorks(){const r=route();return works.filter(w=>(!r.period||w.period===r.period)&&(!r.query||`${w.title} ${w.artist}`.toLocaleLowerCase().includes(r.query.toLocaleLowerCase())));}
function rootSaved(){const list=favoriteIds.map(work).filter(Boolean);return list.length?`<div class="pad"><h2>还想再看一眼。</h2><p class="lede">${list.length} 件收藏 · 保存在本机</p>${tiles(list,'收藏')}</div>`:`<div class="empty">${icon('saved')}<h2>留住让你停下的作品。</h2><p>在画海或作品页点收藏，<br>下次就能从这里继续看。</p><button class="primary" data-tab="sea">去画海看看</button></div>`;}
function workPage(r){const w=work(r.id),p=period(w.period),index=r.ids.indexOf(w.id);return `<button class="work-figure" data-full="${w.id}" aria-label="全屏看${esc(w.title)}">${image(w,true)}</button><div class="work-copy"><button class="author" ${w.by?.[0]?`data-person="${w.by[0]}"`: 'disabled'}>${esc(w.artist)}</button><h2>${esc(w.title)}</h2><div class="meta">${esc(w.yearText)} · ${esc(p.short)}</div><p>${esc(w.summary)}</p><div class="action-strip"><button data-full="${w.id}">${icon('expand')}看全图</button><button data-save="${w.id}" aria-pressed="${favoriteIds.includes(w.id)}">${icon('saved')}${favoriteIds.includes(w.id)?'已收藏':'收藏'}</button></div><div class="collection-context"><button data-work-step="-1" ${index<=0?'disabled':''}>← 上一件</button><span>${esc(r.scope)} · ${index+1} / ${r.ids.length}</span><button data-work-step="1" ${index>=r.ids.length-1?'disabled':''}>下一件 →</button></div><div class="links"><button data-hall="${p.id}">走进${esc(p.short)} ${icon('next')}</button>${readings.filter(x=>x.steps.some(s=>s.works.includes(w.id))).slice(0,2).map(x=>`<button data-story="${x.id}">三分钟看画 · ${esc(x.title)}</button>`).join('')}</div><details class="source"><summary>作品资料与图片来源</summary><p>${esc(w.medium)} · ${esc(w.location)}</p>${w.imageNote?`<p>${esc(w.imageNote)}</p>`:''}${credits[w.id]?`<p>${esc(credits[w.id].author)} · ${esc(credits[w.id].license)}</p><a href="${esc(credits[w.id].source)}" target="_blank" rel="noopener">图片原始来源 ↗</a>`:`<p>${esc(w.noImageReason||'暂无配图')}</p>`}${w.source?`<p><a href="${esc(w.source)}" target="_blank" rel="noopener">作品资料 ↗</a></p>`:''}</details></div>`;}
function personPage(r){const p=people.find(p=>p.id===r.id);const list=works.filter(w=>w.by?.includes(p.id));return `<div class="pad"><div class="person-hero"><div class="eyebrow">认识一位艺术家</div><h2>${esc(p.name)}</h2><p>${esc(p.en)}</p><p>${esc(p.line)}</p></div><div class="section-label"><h3>从作品认识他</h3><small>${list.length} 件</small></div>${tiles(list,'人物作品')}<div class="section-label"><h3>人生片段</h3></div><div class="timeline">${(p.life||[]).map(e=>`<article><time>${esc(e.yearText||e.year)}</time><p>${esc(e.text)}</p></article>`).join('')}</div><div class="section-label"><h3>与他有关的人</h3></div>${Object.entries(p.rel||{}).flatMap(([key,ids])=>ids.map(id=>{const other=people.find(p=>p.id===id);return other?`<button class="list-row" data-person="${id}"><span><strong>${esc(other.name)}</strong><small>${({teachers:'老师',influences:'影响来源',rivals:'对手',patrons:'赞助人'})[key]||key}</small></span>${icon('next')}</button>`:'';})).join('')}</div>`;}
function hallPage(r){const p=period(r.id),list=works.filter(w=>w.period===p.id);return `<div class="pad"><div class="eyebrow">${String(periods.indexOf(p)+1).padStart(2,'0')} / 18 · ${esc(p.span)}</div><h2>${esc(p.name)}</h2><p class="lede">${esc(p.question||p.thesis)}</p><button class="primary" data-work="${list[0].id}" data-scope="本厅">从第一件看 →</button><div class="section-label"><h3>本厅作品</h3><small>${list.length} 件</small></div>${tiles(list,'本厅')}<details class="source"><summary>认识这个时代</summary><p>${esc(p.thesis)}</p>${p.points.map(x=>`<p>${esc(x)}</p>`).join('')}</details></div>`;}
function storyPage(r){const story=readings.find(x=>x.id===r.id);return `<div class="pad"><div class="eyebrow">${story.minutes} 分钟 · ${story.steps.length} 步</div><h2>${esc(story.title)}</h2><p class="lede">${esc(story.deck)}</p><div class="work-figure">${image(work(story.steps[0].works[0]),true)}</div><p class="lede" style="margin-top:20px">先看作品，做一次观察，再按需展开故事。</p><button class="primary" data-read="${story.id}">${readingProgress.has(story.id)?'继续看':'开始看'} →</button><div class="timeline">${story.steps.map((s,i)=>`<article><time>0${i+1}</time><p>${esc(s.title)}</p></article>`).join('')}</div></div>`;}
function readerPage(r){const story=readings.find(x=>x.id===r.id),s=story.steps[r.step],note=r.notes[r.step]||{};return `<article class="reader"><div class="step">${r.step+1} / ${story.steps.length} · ${story.minutes} 分钟看画</div><h2>${esc(s.title)}</h2><div class="reader-images">${s.works.map(id=>`<button data-full="${id}" aria-label="全屏看${esc(work(id).title)}">${image(work(id),true)}</button>`).join('')}</div><p>${esc(s.prompt)}</p>${(s.choices||[]).map((c,i)=>`<button class="choice" data-choice="${i}" aria-pressed="${note.choice===i}">${esc(c.label)}</button>`).join('')}${note.choice!==undefined?`<p role="status">${esc(s.choices[note.choice].response)}</p>`:''}<details data-reading-detail ${note.open?'open':''}><summary>看看解读与背景</summary><p>${esc(s.context)}</p></details></article>`;}
function searchResults(){const q=(route().query||'').trim().toLocaleLowerCase();if(!q)return '<p class="lede">试试「梵高」「蒙娜丽莎」或艺术家的英文名。</p>';const list=works.filter(w=>`${w.title} ${w.artist}`.toLocaleLowerCase().includes(q));const ps=people.filter(p=>`${p.name} ${p.en}`.toLocaleLowerCase().includes(q));return `<p class="lede">${list.length+ps.length} 条结果 · 全部内容</p>${ps.map(p=>`<button class="list-row" data-person="${p.id}"><span><strong>${esc(p.name)}</strong><small>人物 · ${esc(p.en)}</small></span>${icon('next')}</button>`).join('')}${tiles(list,'搜索结果')}${!list.length&&!ps.length?'<p>没有找到，试试更短的名称。</p>':''}`;}
function render(focus=false){const r=route(),immersive=['viewer','reader'].includes(r.kind),dark=r.kind==='viewer'||(r.kind==='root'&&model.tab==='sea');app.className=dark?'dark':'';let title=r.kind==='root'?tabs.find(([id])=>id===model.tab)[1]:({work:'作品',person:'人物',hall:'展厅',story:'导览',reader:'看画',viewer:'全图',search:'搜索'})[r.kind];const header=`<header class="bar">${r.kind==='root'?'<span class="title root-title">三万年长廊</span>':`<button data-back aria-label="${immersive?'退出全屏':'返回上一页'}">${immersive?'完成':icon('back')}</button><span class="title">${title}</span>`}${r.kind==='viewer'?`<button data-zoom>${r.zoom?'复位':'放大'}</button>`:r.kind==='root'&&model.tab==='sea'?`<button data-period aria-label="按时期选择">时期</button><button data-search aria-label="搜索">${icon('explore')}</button>`:r.kind==='search'?'<button data-back>取消</button>':r.kind==='reader'?'<span style="width:44px"></span>':`<button data-search aria-label="搜索">${icon('explore')}</button>`}</header>`;let content='';if(r.kind==='root')content=({sea:rootSea,guide:rootGuide,explore:rootExplore,saved:rootSaved})[model.tab]();else if(r.kind==='work')content=workPage(r);else if(r.kind==='person')content=personPage(r);else if(r.kind==='hall')content=hallPage(r);else if(r.kind==='story')content=storyPage(r);else if(r.kind==='reader')content=readerPage(r);else if(r.kind==='viewer')content=`<div class="full ${r.zoom?'zoom':''}">${image(work(r.id),true)}</div>`;else if(r.kind==='search')content=`<div class="pad"><input class="search-field" id="query" type="search" aria-label="搜索全部作品与人物" placeholder="作品、艺术家、中英文名" value="${esc(r.query)}"><div id="results">${searchResults()}</div></div>`;const footer=r.kind==='viewer'?'':r.kind==='reader'?`<footer class="reader-footer"><button class="primary" data-reader-next>${r.step===readings.find(x=>x.id===r.id).steps.length-1?'完成这一篇':'下一步 →'}</button>${r.step?'<button class="prev" data-reader-prev>← 上一步</button>':''}</footer>`:`<nav class="tabbar" aria-label="主要区域">${tabs.map(([id,label])=>`<button data-tab="${id}" aria-current="${model.tab===id?'page':'false'}">${icon(id)}<span>${label}</span></button>`).join('')}</nav>`;app.innerHTML=header+`<main class="screen" tabindex="-1">${content}</main>`+footer;app.querySelector('.screen').scrollTop=r.scroll||0;if(focus)app.querySelector('.screen').focus({preventScroll:true});if(r.kind==='root'&&model.tab==='sea')bindSea();if(r.kind==='search'){app.querySelector('#query').oninput=e=>{r.query=e.target.value;app.querySelector('#results').innerHTML=searchResults();};}if(r.kind==='reader')app.querySelector('[data-reading-detail]').ontoggle=e=>{r.notes[r.step]={...r.notes[r.step],open:e.target.open};};}
function sheet(kind){const root=document.createElement('div');root.className='sheet';root.innerHTML=`<section role="dialog" aria-modal="true" aria-label="选择时期"><div class="handle"></div><div class="sheet-head"><h2>选择时期</h2><button data-close-sheet>完成</button></div>${kind==='filter'?'<button class="option" data-pick-period="">全部时期</button>':''}${periods.map(p=>`<button class="option" data-pick-period="${p.id}">${esc(p.name)}</button>`).join('')}</section>`;root.dataset.kind=kind;app.querySelectorAll('.bar,.screen,.tabbar').forEach(n=>n.inert=true);app.append(root);root.querySelector('button').focus();root.onclick=e=>{if(e.target===root||e.target.closest('[data-close-sheet]'))closeSheet();};root.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();closeSheet();}if(e.key==='Tab'){const items=[...root.querySelectorAll('button')];if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1).focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0].focus();}}};}
function closeSheet(){app.querySelector('.sheet')?.remove();app.querySelectorAll('[inert]').forEach(n=>n.inert=false);app.querySelector('[data-period],[data-filter]')?.focus();}
function bindSea(){const canvas=app.querySelector('.sea-canvas');let start,drag=false;canvas.onpointerdown=e=>{const rect=canvas.getBoundingClientRect();if(e.clientX-rect.left<24||rect.right-e.clientX<24||!e.isPrimary)return;start={x:e.clientX,y:e.clientY,pan:{...pan}};drag=false;};canvas.onpointermove=e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.hypot(dx,dy)>7){drag=true;canvas.setPointerCapture(e.pointerId);pan={x:Math.max(-130,Math.min(130,start.pan.x+dx)),y:Math.max(-100,Math.min(100,start.pan.y+dy))};app.querySelector('.sea-world').style.transform=`translate(${pan.x}px,${pan.y}px)`;}};canvas.onpointerup=()=>{start=null;};canvas.onpointercancel=()=>{start=null;drag=false;};canvas.addEventListener('click',e=>{if(drag){e.preventDefault();e.stopPropagation();drag=false;}},true);}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset,r=route();if(d.tab)return switchTab(d.tab);if('back'in d)return back();if('search'in d){push({kind:'search',query:''});app.querySelector('#query').focus();return;}if(d.select){if(selected===d.select)return openWork(selected,[selected],'画海');selected=d.select;return render();}if(d.work){let ids=d.scope==='收藏'?favoriteIds:d.scope==='本厅'?works.filter(w=>w.period===r.id).map(w=>w.id):d.scope==='搜索结果'?works.filter(w=>`${w.title} ${w.artist}`.toLocaleLowerCase().includes((r.query||'').toLocaleLowerCase())).map(w=>w.id):d.scope==='人物作品'?works.filter(w=>w.by?.includes(r.id)).map(w=>w.id):d.scope==='探索'?filteredWorks().map(w=>w.id):[d.work];return openWork(d.work,ids,d.scope);}if(d.person)return push({kind:'person',id:d.person});if(d.hall)return push({kind:'hall',id:d.hall});if(d.story)return push({kind:'story',id:d.story});if(d.read)return push(readingProgress.get(d.read)?structuredClone(readingProgress.get(d.read)):{kind:'reader',id:d.read,step:0,notes:{}});if(d.full)return push({kind:'viewer',id:d.full,zoom:false});if(d.save)return toggleFavorite(d.save);if('zoom'in d){r.zoom=!r.zoom;return replace();}if(d.category){r.category=d.category;r.scroll=0;return replace();}if('more'in d){saveView();r.limit=(r.limit||24)+24;return replace();}if('workStep'in d){r.id=r.ids[r.ids.indexOf(r.id)+Number(d.workStep)];r.scroll=0;return replace();}if('readerNext'in d){if(r.step===readings.find(x=>x.id===r.id).steps.length-1){back();return;}r.step++;r.scroll=0;return replace();}if('readerPrev'in d){r.step--;r.scroll=0;return replace();}if('choice'in d){r.notes[r.step]={...r.notes[r.step],choice:Number(d.choice)};saveView();return replace();}if('pause'in d){paused=!paused;return render();}if('seaNext'in d){const ids=['mona-lisa','starry-night','birth-of-venus','impression-sunrise'];selected=ids[(ids.indexOf(selected)+1)%ids.length];pan={x:0,y:0};return render();}if('period'in d)return sheet('sea');if('filter'in d)return sheet('filter');if('pickPeriod'in d){const kind=app.querySelector('.sheet').dataset.kind;closeSheet();if(kind==='filter'){r.period=d.pickPeriod;r.scroll=0;r.limit=24;replace();}else{selected=works.find(w=>w.period===d.pickPeriod&&credits[w.id])?.id||selected;pan={x:0,y:0};render();toast('已选择时期代表作；原型画海仅呈现少量样本');}}});
addEventListener('popstate',e=>{if(e.state?.prototype){if(route().kind==='reader')readingProgress.set(route().id,structuredClone(route()));model=e.state.prototype;render(true);}});
try{[works,periods,people,readings,credits]=await Promise.all(['content/traditions/western/works.json','content/traditions/western/periods.json','content/traditions/western/people.json','content/traditions/western/readings.json','images/credits.json'].map(async path=>{const response=await fetch(new URL(path,base));if(!response.ok)throw Error(path);return response.json();}));people=people.people;history.replaceState({prototype:structuredClone(model)},'');render();}catch(error){app.innerHTML='<p class="loading">原型内容加载失败，请通过本地开发服务器打开并刷新。</p>';console.error(error);}
